def remove_member(self, member_id):
    try:
        person = Person.query.get(member_id, self)
    except orm.exc.NoResultFound:
        return None
    if not person.has_bills():
        db.session.delete(person)
        db.session.commit()
    else:
        person.activated = False
        db.session.commit()
    return person

